function cats(){const m={};EXTRA.forEach(x=>{if(x&&x.name)m[x.name]=0});Q.forEach(q=>m[q.cat]=(m[q.cat]||0)+1);const ix=c=>{const i=ORD.indexOf(c);return i<0?1e4:i};return Object.keys(m).sort((a,b)=>ix(a)-ix(b)||a.localeCompare(b)).map(c=>[c,m[c]])}
